/**
 * Start (or resume) online payment for a PENDING_PAYMENT order
 */
export const createPaymentIntent = <ThrowOnError extends boolean = false>(
  options: Options<CreatePaymentIntentData, ThrowOnError>,
): RequestResult<
  CreatePaymentIntentResponses,
  CreatePaymentIntentErrors,
  ThrowOnError
> =>
  (options.client ?? client).post<
    CreatePaymentIntentResponses,
    CreatePaymentIntentErrors,
    ThrowOnError
  >({
    security: [{ scheme: "bearer", type: "http" }],
    url: "/orders/{orderId}/payment-intent",
    ...options,
  });

/**
 * Dev only (PAYMENT_PROVIDER=fake) — simulate a successful provider capture
 */
export const simulatePaymentCapture = <ThrowOnError extends boolean = false>(
  options: Options<SimulatePaymentCaptureData, ThrowOnError>,
): RequestResult<
  SimulatePaymentCaptureResponses,
  SimulatePaymentCaptureErrors,
  ThrowOnError
> =>
  (options.client ?? client).post<
    SimulatePaymentCaptureResponses,
    SimulatePaymentCaptureErrors,
    ThrowOnError
  >({ url: "/payments/{paymentId}/simulate-capture", ...options });

/**
 * Register an Expo push token to be notified when the order is ready (customer app)
 */
export const registerPushSubscription = <ThrowOnError extends boolean = false>(
  options: Options<RegisterPushSubscriptionData, ThrowOnError>,
): RequestResult<
  RegisterPushSubscriptionResponses,
  RegisterPushSubscriptionErrors,
  ThrowOnError
> =>
  (options.client ?? client).post<
    RegisterPushSubscriptionResponses,
    RegisterPushSubscriptionErrors,
    ThrowOnError
  >({
    security: [{ scheme: "bearer", type: "http" }],
    url: "/orders/{orderId}/push-subscriptions",
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

/**
 * Server-Sent Events with status changes of one order (customer tracking)
 */
export const streamOrderEvents = <ThrowOnError extends boolean = false>(
  options: Options<
    StreamOrderEventsData,
    ThrowOnError,
    StreamOrderEventsResponse
  >,
): Promise<ServerSentEventsResult<StreamOrderEventsResponses>> =>
  (options.client ?? client).sse.get<
    StreamOrderEventsResponses,
    StreamOrderEventsErrors,
    ThrowOnError
  >({
    security: [{ scheme: "bearer", type: "http" }],
    url: "/orders/{orderId}/events",
    ...options,
  });

/**
 * Server-Sent Events for the queue display
 */
export const streamQueueEvents = <ThrowOnError extends boolean = false>(
  options?: Options<
    StreamQueueEventsData,
    ThrowOnError,
    StreamQueueEventsResponse
  >,
): Promise<ServerSentEventsResult<StreamQueueEventsResponses>> =>
  (options?.client ?? client).sse.get<
    StreamQueueEventsResponses,
    unknown,
    ThrowOnError
  >({ url: "/queue/events", ...options });

/**
 * Stripe webhook (signature verified with STRIPE_WEBHOOK_SECRET)
 */
export const stripeWebhook = <ThrowOnError extends boolean = false>(
  options: Options<StripeWebhookData, ThrowOnError>,
): RequestResult<StripeWebhookResponses, StripeWebhookErrors, ThrowOnError> =>
  (options.client ?? client).post<
    StripeWebhookResponses,
    StripeWebhookErrors,
    ThrowOnError
  >({
    url: "/payments/webhooks/stripe",
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });
